   400|                            const tempBtn = document.createElement('button');
   401|                            tempBtn.type = 'submit';
   402|                            tempBtn.style.display = 'none';
   403|                            form.appendChild(tempBtn);
   404|                            tempBtn.click();
   405|                            tempBtn.remove();
   406|                            throw new Error('Form validation failed');
   407|                        }
   408|                        
   409|                        const product = document.getElementById('productInput').value;
   410|                        const amount = prices[product].toFixed(2);
   411|                        
   412|                        return actions.order.create({
   413|                            purchase_units: [{
   414|                                amount: { value: amount, currency_code: 'USD' }
   415|                            }]
   416|                        });
   417|                    },
   418|                    onApprove: function(data, actions) {
