   421|                            document.getElementById('order-form').submit();
   422|                        });
   423|                    },
   424|                    onError: function(err) {
   425|                        console.error('PayPal error:', err);
   426|                        document.getElementById('paypalPlaceholder').style.display = 'block';
   427|                    }
   428|                }).render('#paypal-button-container');
   429|            } catch (e) {
   430|                console.error('PayPal init failed:', e);
   431|                document.getElementById('paypalPlaceholder').style.display = 'block';
   432|            }
   433|        } else {
   434|            document.getElementById('paypalPlaceholder').style.display = 'block';
   435|        }
   436|    </script>
